def control(obs):
    global start_t
    if start_t is None: start_t = obs.get('t', 0.0)
    elapsed = obs.get('t', 0.0) - start_t
    h = obs.get('hitch_deg', 0.0)
    if elapsed < 2.0:
        return (max(-5.0, min(5.0, -0.5*h)), 0.4, 0.0)
    # Move trailer rear away from the repeatedly contacted left rail.
    steer = max(2.0, min(9.0, 6.0 - 0.25*h))
    return (steer, -0.25, -23.0)

