import math
def control(obs):
    h = obs.get('hitch_deg', 0.0)
    rails = []
    views = obs.get('views', {})
    for name in ('direct', 'left_mirror', 'right_mirror'):
        view = views.get(name) or {}
        for b, d in view.get('walls', []):
            # Keep rearward wall points and express them as lateral offsets.
            if abs(b) > 90 and d < 16:
                y = d * math.sin(math.radians(b))
                if abs(y) < 8:
                    rails.append(y)
    steer = 1.5 * h
    if len(rails) >= 2:
        left = max((y for y in rails if y > 0), default=None)
        right = min((y for y in rails if y < 0), default=None)
        if left is not None and right is not None:
            midpoint = (left + right) / 2.0
            steer -= 4.0 * midpoint
    steer = max(-12.0, min(12.0, steer))
    return (steer, -0.28, -170.0)

