def control(obs):
    h = obs.get('hitch_deg', 0.0)
    ys = []
    for view in (obs.get('views') or {}).values():
        for b, d in view.get('walls', []):
            if abs(b) > 90 and d < 9:
                y = d * math.sin(math.radians(b))
                if abs(y) < 7:
                    ys.append(y)
    left = max((y for y in ys if y > 0.5), default=None)
    right = min((y for y in ys if y < -0.5), default=None)
    steer = 1.2 * h
    if left is not None and right is not None:
        steer -= 1.0 * (left + right) / 2.0
    steer = max(-8.0, min(8.0, steer))
    return (steer, -0.18, -170.0)

