import math
phase='recover'
recover_t=0.0
def control(obs):
    global phase,recover_t
    h=obs.get('hitch_deg',0.0)
    status=obs.get('status','')
    if phase=='recover':
        recover_t += obs.get('dt',0.1)
        # Pull forward briefly to release the rail contact and straighten.
        if recover_t < 5.0 or status=='PINNED':
            return (max(-12.0,min(12.0,-0.8*h)),0.45,-41)
        phase='reverse'
    steer=max(-10.0,min(10.0,0.7*h))
    return (steer,-0.45,-41)

