import math
phase='reset'
t=0.0
def control(obs):
    global phase,t
    t += obs.get('dt',0.1)
    h=obs.get('hitch_deg',0.0)
    if phase=='reset':
        if t < 7.0:
            return (0.0,0.55,-41)
        phase='back'
    cam=obs.get('views',{}).get('camera') or {}
    left=[]; right=[]
    for b,d in cam.get('walls',[]):
        if 0<d<12:
            if 90<=b<=180: left.append(d)
            elif -180<=b<=-90: right.append(d)
    bias=0.0
    if left and right: bias=max(-7.0,min(7.0,2.0*(min(right)-min(left))))
    elif left: bias=4.0
    elif right: bias=-4.0
    steer=max(-18.0,min(18.0,-0.55*h+bias))
    return (steer,-0.48,-41)

